	if (fuhao.includes(char) ) length += 0.5;
	else length += 1;
	}
//大于18个全角字符
if (length > 18) '《'+book.name+'》'
else '&#10;'
}}
{{
let zx = java.getString('class.divbox@h3@a@text');
let temp=java.getStringList('class.tabcontent@class.tabvalue.1@td[0:3,9,10]@text');
rr=Object.values(temp);
//处理rr
[rr[0], rr[2]] = [rr[2], rr[0]];
rr[0] = '最新：' + String(zx).replace(/^正文|^\s+/,'') + String(rr[0]).replace('最后更新：',' ').replaceAll('-','/') + String(rr[1]).replace(/连载状态：(.+)/,' ($1)');
delete rr[1];
rr[2] = String(rr[2]).replace(/作品分类：\s*/,'分类：') + String(rr[3]).replace(/作品性质：(.+)/,' ($1)');
delete rr[3];
rr[4] = String(rr[4]).replace(/总点击数：\s*/,'点击：') + String(rr[5]).replace(/本月点击：(.+)/,'　$1 (月)');
delete rr[5];
//评分
let pf=java.getString('.ratediv@text');
let r0 = rr.join('\n') + '\n' + String(pf).replace(/评分：\s*/,'评分：');
//简介
let r1=java.getString('.tabcontent .tabvalue:eq(0) div@html');
if (r1=="") {r1='';}
else {
 r1 = '\n简介：\n' + String(r1).replace(/[\u3000\u2003]{2}/g,'\n').replace('「','“').replace('」','”').replace(/\>\s*内容简介/,'')
	}
//评论
